content.css:
.pbh{position:sticky;top:0;z-index:100;background:color-mix(in srgb, var(--color-bg, #fff) 94%, transparent);border-bottom:1px solid var(--color-border-subtle, #f0f0f0);font-family:var(--font-body, system-ui, sans-serif)}
.pbh-inner{display:flex;align-items:center;gap:2rem;max-width:var(--wide-width, 1200px);margin:0 auto;padding:0 1.5rem;height:64px}
.pbh-logo,.pbh-panel-logo{font-family:var(--font-heading, inherit);font-size:1.125rem;font-weight:600;letter-spacing:-0.015em;color:var(--color-text, #1a1a1a);text-decoration:none}
.pbh-nav{display:flex;gap:1.25rem;font-size:0.875rem;margin-inline-start:auto}
.pbh-nav a{color:var(--color-text, #1a1a1a);text-decoration:none;transition:color 120ms ease}
.pbh-nav a:hover{color:var(--color-brand, #0066cc)}
.pbh-check{display:none}
.pbh-burger{display:none;flex-direction:column;justify-content:center;gap:4px;width:36px;height:36px;padding:8px;cursor:pointer;margin-inline-start:auto}
.pbh-burger span{display:block;height:2px;background:var(--color-text, #1a1a1a);border-radius:1px}
.pbh-scrim{position:fixed;inset:0;background:rgba(0,0,0,.4);opacity:0;pointer-events:none;transition:opacity 120ms ease;z-index:205}
.pbh-panel{position:fixed;top:0;inset-inline-end:0;height:100vh;width:min(300px,85vw);background:var(--color-bg, #fff);border-inline-start:1px solid var(--color-border, #e5e5e5);transform:translateX(100%);transition:transform 200ms ease;z-index:210;display:flex;flex-direction:column;gap:1.25rem;padding:1.25rem}
.pbh-check:checked ~ .pbh-scrim{opacity:1;pointer-events:auto}
.pbh-check:checked ~ .pbh-panel{transform:none}
.pbh-panel-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--color-border-subtle, #f0f0f0);padding-bottom:0.75rem}
.pbh-close{font-size:1.5rem;line-height:1;color:var(--color-muted, #8b8b8b);cursor:pointer}
.pbh-panel-nav{display:flex;flex-direction:column;gap:1rem;font-size:1.125rem}
.pbh-panel-nav a{color:var(--color-text, #1a1a1a);text-decoration:none}
@media (max-width:720px){.pbh-inner{gap:1rem;padding:0 1rem}.pbh-nav{display:none}.pbh-burger{display:flex}}
@media (prefers-reduced-motion:reduce){.pbh-panel{transition:none}.pbh-scrim{transition:none}}
